DEST_DIR = "/home/safin313/Downloads/transify-main/src/frontend/static/photos"
ICONS_DIR = "/home/safin313/Downloads/transify-main/src/frontend/static/icons"
os.makedirs(DEST_DIR, exist_ok=True)
os.makedirs(ICONS_DIR, exist_ok=True)

# 1. Photographic assets mapping
PHOTO_MAP = {
    "care-hero-bangladesh": os.path.join(BRAIN_DIR, "care_hero_bangladesh_1795162258161.jpg"),
    "care-sign-communication": os.path.join(BRAIN_DIR, "care_sign_communication_1795162258401.jpg"),
    "care-braille-access": os.path.join(BRAIN_DIR, "care_braille_access_1795162257368.jpg"),
    "care-voice-intake": os.path.join(BRAIN_DIR, "care_voice_intake_1795162257228.jpg"),
}

# Tone curve lookup table: lift shadows slightly by 8
LUT = [int(min(255, 8 + ((i / 255.0) ** 0.97) * (255 - 8))) for i in range(256)] * 3

def encode_avif(in_path, out_path):
    cmd = [
        "ffmpeg", "-y", "-i", in_path,
        "-c:v", "libsvtav1", "-crf", "35",
        "-pix_fmt", "yuv420p",
        out_path
    ]
    subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=True)

for name, src_path in PHOTO_MAP.items():
    if not os.path.exists(src_path):
        print(f"Skipping {name}, {src_path} not found")
        continue
    img = Image.open(src_path).convert("RGB")
    # Grade: reduce sat 12%, lift shadows
    img = ImageEnhance.Color(img).enhance(0.88).point(LUT)
    
    # Save WebP
    webp_path = os.path.join(DEST_DIR, f"{name}.webp")
    img.save(webp_path, "WEBP", quality=78, method=6)
    
    # Save JPG
    jpg_path = os.path.join(DEST_DIR, f"{name}.jpg")
    img.save(jpg_path, "JPEG", quality=82, progressive=True, optimize=True)
    
    # Save 24px LQIP
    lqip_w = 24
    lqip_h = max(16, int(24 * (img.height / img.width)))
    lqip = img.resize((lqip_w, lqip_h), Image.Resampling.LANCZOS).filter(ImageFilter.GaussianBlur(1.0))
    lqip.save(os.path.join(DEST_DIR, f"{name}_lqip.jpg"), "JPEG", quality=40)
    
    # Encode AVIF
    avif_path = os.path.join(DEST_DIR, f"{name}.avif")
    try:
        encode_avif(jpg_path, avif_path)
    except Exception as e:
        print(f"AVIF error for {name}: {e}")
        
    print(f"Processed Photo Asset: {name} (WebP, JPG, LQIP, AVIF)")

